class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return (self.width + self.height) * 2

    def is_square(self):
        return self.width == self.height


n = int(input())
for _ in range(n):
    w, h = map(int, input().split())
    rect = Rectangle(w, h)
    text = f"넓이 {rect.area()}, 둘레 {rect.perimeter()}"
    if rect.is_square():
        text += ", 정사각형"
    print(text)
